} else if (key === "Escape") {
  preventEvent(event);
  // If the currently focused menu item has an open submenu, close it and keep focus on the item.
  if (this.currentMenuItem.isSubmenuItem && this.currentMenuItem.elements.toggle.isOpen) {
    this.currentMenuItem.elements.toggle.close();
    this.currentMenuItem.focus();
  } else {
    // Otherwise close the submenu that opened this menu (i.e., the parent menu item's submenu)
    // and move focus to that parent menu item.
    const parentMenu = this.elements.parentMenu;
    if (parentMenu && parentMenu.currentMenuItem.isSubmenuItem) {
      parentMenu.currentMenuItem.elements.toggle.close();
      parentMenu.focusCurrentChild();
    }
  }
}
